from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from silk.models import Profile as SilkProfile

class SilkProfileTracebackView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, profile_id):
        # Restrict profile traceback inspection to profiles initiated by caller
        profile_obj = SilkProfile.objects.filter(
            id=profile_id,
            request__user_id=request.user.id
        ).first()
        if not profile_obj:
            return Response({"error": "Profile not found or access denied"}, status=status.HTTP_404_NOT_FOUND)

        return Response({
            "name": profile_obj.name,
            "file_path": profile_obj.file_path,
            "line_num": profile_obj.line_num,
            "execution_time": profile_obj.time_taken
        }, status=status.HTTP_200_OK)
